css:
.ts-sim-container {
    padding: 28px 24px 60px 24px;
    background: #07101e;
    background-image:
        radial-gradient(circle at 20% 0%, rgba(0,191,255,0.08), transparent 45%),
        radial-gradient(circle at 90% 100%, rgba(0,255,136,0.06), transparent 50%);
    min-height: 100vh;
    font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif;
    color: #d8e0ec;
}

.ts-sim-header {
    border-left: 4px solid #00ff88;
    padding: 18px 24px 22px 24px;
    margin-bottom: 24px;
    background: rgba(0,255,136,0.04);
    border-radius: 0 8px 8px 0;
}
.ts-sim-header-tag {
    font-size: 0.68rem;
    letter-spacing: 0.2em;
    color: #00bfff;
    text-transform: uppercase;
    margin-bottom: 10px;
    font-weight: 600;
}
.ts-sim-header h1 {
    color: #00ff88;
    font-size: 1.55rem;
    letter-spacing: 0.04em;
    margin: 0 0 8px 0;
    font-weight: 700;
}
.ts-sim-header-sub {
    color: #8a9bb4;
    font-size: 0.92rem;
}

.ts-sim-period-bar {
    display: flex;
    align-items: center;
    gap: 18px;
    background: #0d1828;
    border: 1px solid #1f2d3d;
    border-radius: 6px;
    padding: 12px 18px;
    margin-bottom: 22px;
}
.ts-sim-period-label {
    color: #00bfff;
    font-size: 0.78rem;
    text-transform: uppercase;
    letter-spacing: 0.14em;
    white-space: nowrap;
    font-weight: 600;
}
.ts-sim-period-label span#currentDay,
.ts-sim-period-label span#maxPeriods {
    color: #00ff88;
    font-weight: 700;
    font-size: 1.05rem;
}
.ts-sim-period-progress {
    flex: 1;
    height: 6px;
    background: #1f2d3d;
    border-radius: 3px;
    overflow: hidden;
}
.ts-sim-period-progress-fill {
    height: 100%;
    width: 12.5%;
    background: linear-gradient(90deg, #00bfff, #00ff88);
    transition: width 0.4s ease;
}

.ts-sim-kpi-grid {
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(220px, 1fr));
    gap: 14px;
    margin-bottom: 24px;
}
.ts-sim-kpi-card {
    background: #0d1828;
    border: 1px solid #1f2d3d;
    border-radius: 8px;
    padding: 18px 20px;
    position: relative;
    overflow: hidden;
}
.ts-sim-kpi-card::before {
    content: '';
    position: absolute;
    top: 0; left: 0; right: 0;
    height: 2px;
    background: linear-gradient(90deg, #00ff88, #00bfff);
}
.ts-sim-kpi-label {
    color: #6b7c95;
    font-size: 0.66rem;
    text-transform: uppercase;
    letter-spacing: 0.16em;
    margin-bottom: 8px;
    font-weight: 600;
}
.ts-sim-kpi-value {
    font-size: 1.85rem;
    font-weight: 700;
    color: #00ff88;
    letter-spacing: 0.02em;
}
.ts-sim-kpi-sub {
    color: #6b7c95;
    font-size: 0.72rem;
    margin-top: 6px;
}

.ts-sim-briefing {
    background: #0d1828;
    border: 1px solid #1f2d3d;
    border-left: 3px solid #00bfff;
    border-radius: 6px;
    padding: 22px 26px;
    margin-bottom: 22px;
}
.ts-sim-briefing-tag {
    font-size: 0.68rem;
    letter-spacing: 0.18em;
    color: #00bfff;
    text-transform: uppercase;
    font-weight: 600;
    margin-bottom: 8px;
    display: flex;
    gap: 12px;
}
.ts-sim-briefing-tag span:nth-child(2) {
    color: #ff6b35;
}
.ts-sim-briefing h3 {
    color: #e8eef7;
    font-size: 1.12rem;
    margin: 0 0 10px 0;
    font-weight: 600;
}
.ts-sim-briefing-body {
    color: #c2cbdc;
    font-size: 0.94rem;
    line-height: 1.55;
}
.ts-sim-formula {
    margin-top: 14px;
    background: #07101e;
    border: 1px solid #1f2d3d;
    border-radius: 4px;
    padding: 12px 14px;
    color: #00ff88;
    font-family: 'SF Mono', 'Consolas', monospace;
    font-size: 0.86rem;
    letter-spacing: 0.02em;
}
.ts-sim-formula:empty { display: none; }

.ts-sim-controls {
    background: #0d1828;
    border: 1px solid #1f2d3d;
    border-radius: 8px;
    padding: 22px 24px;
    margin-bottom: 24px;
}
.ts-sim-controls h3 {
    color: #00bfff;
    font-size: 0.84rem;
    text-transform: uppercase;
    letter-spacing: 0.16em;
    margin: 0 0 16px 0;
    font-weight: 700;
}
.ts-sim-controls label {
    display: block;
    color: #8a9bb4;
    font-size: 0.78rem;
    text-transform: uppercase;
    letter-spacing: 0.1em;
    margin-bottom: 8px;
    font-weight: 600;
}
.ts-sim-select {
    background: #07101e;
    border: 1px solid #2d3f55;
    color: #e0e6f0;
    border-radius: 4px;
    padding: 10px 12px;
    width: 100%;
    font-size: 0.92rem;
    font-family: inherit;
}
.ts-sim-select option {
    background: #0d1828;
    color: #e0e6f0;
    padding: 8px;
}
.ts-sim-rationale-wrap {
    margin-top: 16px;
}
.ts-sim-controls input[type="text"] {
    background: #07101e;
    border: 1px solid #2d3f55;
    color: #e0e6f0;
    border-radius: 4px;
    padding: 10px 12px;
    width: 100%;
    font-size: 0.92rem;
}
.ts-sim-controls input[type="text"]::placeholder {
    color: #56657c;
}
.ts-sim-button-row {
    display: flex;
    gap: 10px;
    margin-top: 18px;
    flex-wrap: wrap;
}
.ts-sim-container .btn-primary {
    background: linear-gradient(135deg, #00ff88, #00bfff);
    border: none;
    color: #07101e;
    font-weight: 700;
    padding: 11px 22px;
    text-transform: uppercase;
    letter-spacing: 0.1em;
    font-size: 0.84rem;
    border-radius: 4px;
    transition: transform 0.18s ease, box-shadow 0.18s ease;
}
.ts-sim-container .btn-primary:hover {
    transform: translateY(-1px);
    box-shadow: 0 4px 14px rgba(0,255,136,0.35);
    color: #07101e;
}
.ts-sim-container .btn-outline-secondary {
    background: transparent;
    border: 1px solid #2d3f55;
    color: #8a9bb4;
    padding: 9px 16px;
    border-radius: 4px;
    font-size: 0.78rem;
    text-transform: uppercase;
    letter-spacing: 0.08em;
}
.ts-sim-container .btn-outline-secondary:hover {
    border-color: #ff6b35;
    color: #ff6b35;
    background: transparent;
}

.ts-sim-row {
    display: grid;
    grid-template-columns: 1fr 1fr;
    gap: 16px;
    margin-bottom: 22px;
}
.ts-sim-chart-card {
    background: #0d1828;
    border: 1px solid #1f2d3d;
    border-radius: 8px;
    padding: 18px;
}
.ts-sim-card-title {
    color: #00bfff;
    font-size: 0.78rem;
    text-transform: uppercase;
    letter-spacing: 0.14em;
    margin-bottom: 14px;
    font-weight: 700;
}
.ts-sim-chart-wrap {
    height: 260px;
    position: relative;
}

.ts-sim-history-card {
    background: #0d1828;
    border: 1px solid #1f2d3d;
    border-radius: 8px;
    padding: 18px 22px;
}
.ts-sim-history-card table {
    color: #c2cbdc;
    margin: 0;
    font-size: 0.86rem;
}
.ts-sim-history-card thead th {
    color: #00bfff;
    border-bottom: 1px solid #1f2d3d;
    font-size: 0.72rem;
    text-transform: uppercase;
    letter-spacing: 0.1em;
    font-weight: 700;
}
.ts-sim-history-card tbody td {
    border-top: 1px solid #1a2738;
    padding: 8px 6px;
}

@media (max-width: 768px) {
    .ts-sim-row { grid-template-columns: 1fr; }
    .ts-sim-header h1 { font-size: 1.2rem; }
    .ts-sim-kpi-value { font-size: 1.4rem; }
    .ts-sim-container { padding: 18px 14px 40px 14px; }
}


/* a11y: visible keyboard focus on every interactive control */
.ts-sim-container .ts-sim-select:focus-visible,
.ts-sim-container input:focus-visible,
.ts-sim-container button:focus-visible {
    outline: 3px solid #00ff88;
    outline-offset: 2px;
}

.ts-sim-complete {
    margin: 18px 0 24px 0;
    padding: 20px 22px;
    border: 1px solid #1f4a38;
    border-radius: 10px;
    background: #0b1a17;
    color: #dbe6f2;
}
.ts-sim-complete h3 { margin: 0 0 6px 0; color: #00ff88; }
.ts-sim-complete-band { margin: 0 0 10px 0; font-weight: 600; color: #9fe8c4; }
.ts-sim-complete-kpis { margin: 0 0 12px 18px; padding: 0; }
.ts-sim-complete-kpis li { margin: 2px 0; }
.ts-sim-done-score { font-weight: 600; color: #00ff88; }

@media (prefers-reduced-motion: reduce) {
    .ts-sim-container *,
    .ts-sim-container *::before,
    .ts-sim-container *::after {
        animation-duration: 0.001ms !important;
        animation-iteration-count: 1 !important;
        transition-duration: 0.001ms !important;
        scroll-behavior: auto !important;
    }
}

