        initialize(state) {
            if (!state.domainState || Object.keys(state.domainState).length === 0) {
                state.domainState = {
                    mape: 18.0,
                    mase: 1.62,
                    coverage: null,
                    cumulativeScore: 0,
                    mapeHistory: [],
                    maseHistory: [],
                    scoreHistory: [],
                    decisionLog: [],
                    forecastBaseline: this._buildBaselineSeries(),
                    forecastPath: this._buildForecastSeries(0)
                };
            }
            if (!state.decisions || Object.keys(state.decisions).length === 0) {
                // No pre-selected answer: the old default pre-filled the correct option.
                state.decisions = { choice: '', rationale: '' };
            }
            this._renderedRound = null;
            this._updateBriefing(state);
            this._syncControlsFromDecisions(state);
        }

        _syncControlsFromDecisions(state) {
            var dec = (state && state.decisions) || {};
            var sel = document.getElementById('choiceSelect');
            if (sel && dec.choice !== undefined && dec.choice !== null && dec.choice !== '') {
                sel.value = this._choiceCode(state, dec.choice);
            }
            var rat = document.getElementById('rationaleInput');
            if (rat && dec.rationale !== undefined && dec.rationale !== null) {
                rat.value = String(dec.rationale);
            }
        }

        // On screen each option value is a round code such as r3o_2 instead of the bare 0 to 3, so the EQIL
        // guard shuffles the list per game (it keeps all-numeric lists in their original order, and the
        // rigorous answer was always the last one). decisions.choice and the scoring keep the bare value.
        // The code format also sets the fixed order of the Open player (no game id): with it no single
        // position scores more than 8 of 16 points across the eight rounds.
        _choiceCode(state, val) {
            var idx = Math.min(((state && state.currentPeriod) || 1) - 1, this.ROUNDS.length - 1);
            return 'r' + this.ROUNDS[idx].id + 'o_' + val;
        }

        _choiceVal(code) {
            var s = String(code === undefined || code === null ? '' : code);
            var k = s.lastIndexOf('_');
            return k >= 0 ? s.slice(k + 1) : s;
        }

        _lang() {
            // window.mySimulation.language is the framework property. .currentLanguage
            // does not exist and reads undefined, which silently falls back to English.
            // The Open player keeps the language in .lang instead, so read that when .language is absent.
            var l = (window.mySimulation && (window.mySimulation.language || window.mySimulation.lang)) || 'en';
            return String(l).split('-')[0].toLowerCase();
        }

        _t(key, fallback) {
            try {
                var v = window.mySimulation.t(key);
                if (v && v !== key) return v;
            } catch (e) {}
            return fallback;
        }

        _round(idx) {
            var base = this.ROUNDS[idx];
            if (this._lang() !== 'es') return base;
            var es = this.ROUNDS_ES && this.ROUNDS_ES[base.id];
            if (!es) return base;
            return {
                id: base.id,
                title: es.title || base.title,
                description: es.description || base.description,
                formula: es.formula || base.formula,
                options: base.options.map(function(o, i) {
                    return { val: o.val, text: (es.options && es.options[i]) || o.text, score: o.score };
                })
            };
        }
        validateDecisions(decisions) {
            // Read the controls FIRST. The previous version re-rendered the briefing here,
            // which rebuilt the select and force-selected the last option, so the reads
            // below always returned the correct answer instead of the player choice.
            var sel = document.getElementById('choiceSelect');
            if (sel) decisions.choice = this._choiceVal(sel.value);

            var rat = document.getElementById('rationaleInput');
            if (rat) decisions.rationale = rat.value || '';

            if (decisions.choice === undefined || decisions.choice === null || decisions.choice === '') {
                window.mySimulation.uiManager.showNotification(
                    window.mySimulation.t('choice_warning'), 'warning'
                );
                return false;
            }
            return true;
        }
        calculateResults(state) {
            // Thin wrapper: the round model lives in _computeRound so this method stays
            // short and its return statement is visible to static validators, current and
            // legacy alike. Keep this comment free of apostrophes, quotes and backticks:
            // the importer treats any of them as a string delimiter and desyncs its brace
            // counter, which produced the false empty-method and missing-return errors.
            return this._computeRound(state);
        }

        _computeRound(state) {
            var roundIdx = (state.currentPeriod || 1) - 1;
            var round = this._round(Math.min(roundIdx, this.ROUNDS.length - 1));
            var decisions = state.decisions || {};
            var picked = round.options.find(function(o) { return o.val === decisions.choice; });
            if (!picked) picked = round.options[0];

            var score = picked.score;
            state.domainState.cumulativeScore += score;

            var s = state.domainState.cumulativeScore;
            var maxS = 16;
            var frac = Math.min(s / maxS, 1);

            var newMape = 18.0 - frac * (18.0 - 11.2);
            if (score === 0 && roundIdx >= 4) newMape += 0.6;
            if (score === 0 && roundIdx >= 6) newMape += 0.4;

            var newMase = 1.62 - frac * (1.62 - 0.71);
            var newCoverage = 50 + frac * (94 - 50);

            state.domainState.mape = Math.round(newMape * 10) / 10;
            state.domainState.mase = Math.round(newMase * 100) / 100;
            state.domainState.coverage = Math.round(newCoverage);
            state.domainState.mapeHistory.push(state.domainState.mape);
            state.domainState.maseHistory.push(state.domainState.mase);
            state.domainState.scoreHistory.push(state.domainState.cumulativeScore);
            state.domainState.forecastPath = this._buildForecastSeries(frac);
            // platform score: methodology points so far over the 16 point maximum, the same totalScore over maxScore percentage getPerformanceSummary reports as overallScore
            state.domainState.performance = Object.assign({}, state.domainState.performance || {}, { overallScore: Math.max(0, Math.min(100, Math.round(state.domainState.cumulativeScore / (this.ROUNDS.length * 2) * 100))) });

            state.domainState.decisionLog.push({
                round: roundIdx + 1,
                title: round.title,
                choice: picked.text,
                score: score,
                rationale: decisions.rationale || ''
            });

            var self = this;
            var nextPeriod = (state.currentPeriod || 1) + 1;
            setTimeout(function() {
                // Pass the real state with the advanced period so _updateBriefing can see
                // domainState and history, not a synthetic two-field object.
                var live = (window.mySimulation && window.mySimulation.state) || state;
                var view = Object.assign({}, live, { currentPeriod: nextPeriod });
                self._updateBriefing(view);
            }, 450);

            var feedback = score === 2
                ? this._t('fb_strong', 'Rigorous move. Diagnostic discipline locked in.')
                : score === 1
                    ? this._t('fb_partial', 'Defensible but not the strongest answer for this step.')
                    : this._t('fb_weak', 'That move violates the workflow - see the AI-coach feedback.');

            return {
                period: state.currentPeriod,
                roundTitle: round.title,
                choice: picked.text,
                score: score,
                mape: state.domainState.mape,
                mase: state.domainState.mase,
                coverage: state.domainState.coverage,
                feedback: feedback,
                rationale: decisions.rationale || ''
            };
        }


        setupUI(uiManager) {
            uiManager.bind('currentDay', 'currentPeriod');
            uiManager.bind('maxPeriods', 'maxPeriods');
            uiManager.bind('mapeDisplay', 'domainState.mape',
                function(v) { return (v === null || v === undefined) ? '--' : v.toFixed(1) + '%'; });
            uiManager.bind('maseDisplay', 'domainState.mase',
                function(v) { return (v === null || v === undefined) ? '--' : v.toFixed(2); });
            uiManager.bind('calibDisplay', 'domainState.coverage',
                function(v) { return (v === null || v === undefined) ? '--' : v + '%'; });
            uiManager.bind('scoreDisplay', 'domainState.cumulativeScore',
                function(v) { return (v || 0) + ' / 16'; });

            var origRender = uiManager.render ? uiManager.render.bind(uiManager) : null;
            uiManager.render = function(state) {
                if (origRender) origRender(state);
                var fill = document.getElementById('progressFill');
                if (fill && state) {
                    var pct = Math.min(((state.currentPeriod || 1) / (state.maxPeriods || 8)) * 100, 100);
                    fill.style.width = pct + '%';
                }
            };

            // Repaint the round text when the player switches language, so the briefing and options follow the new language.
            if (!this._langWired) {
                var langSelf = this;
                document.addEventListener('express:langchanged', function() {
                    try { langSelf._updateBriefing(window.mySimulation.state); } catch (e) {}
                });
                this._langWired = true;
            }
        }

