                                title: { display: true, text: this._t('chart_axis_units', 'Units (thousand litres)'), color: '#8a9bb4', font: { size: 10 } }
                            },
                            x: {
                                ticks: { color: '#8a9bb4', maxTicksLimit: 12 },
                                grid: { color: '#1f2d3d' }
                            }
                        }
                    }
                }
            };
        }

        getChartData(state) {
            var rounds = (state.domainState.mapeHistory || []).map(function(_, i) { return 'R' + (i + 1); });
            var baseline = rounds.map(function() { return 18.0; });
            var floor = rounds.map(function() { return 11.2; });

            var hist = state.domainState.forecastBaseline || [];
            var forecast = state.domainState.forecastPath || { labels: [], point: [], upper: [], lower: [] };

            // Month labels are stored in English in domainState; translate the month part at render time.
            var enMonths = ['Jan', 'Feb', 'Mar', 'Apr', 'May', 'Jun', 'Jul', 'Aug', 'Sep', 'Oct', 'Nov', 'Dec'];
            var trMonths = String(this._t('months_short', enMonths.join(','))).split(',');
            var trLabel = function(lab) {
                var parts = String(lab).split(' ');
                var mi = enMonths.indexOf(parts[0]);
                return (mi >= 0 && trMonths.length === 12) ? trMonths[mi] + (parts.length > 1 ? ' ' + parts.slice(1).join(' ') : '') : lab;
            };
            var allLabels = hist.map(function(p) { return trLabel(p.label); }).concat(forecast.labels.map(trLabel));
            var historicalSeries = hist.map(function(p) { return p.value; }).concat(forecast.labels.map(function() { return null; }));
            var pointSeries = hist.map(function() { return null; }).concat(forecast.point);
            var upperSeries = hist.map(function() { return null; }).concat(forecast.upper);
            var lowerSeries = hist.map(function() { return null; }).concat(forecast.lower);

            return {
                mapeChart: {
                    labels: rounds,
                    datasets: [
                        { data: state.domainState.mapeHistory },
                        { label: this._t('chart_ds_baseline', 'Excel baseline (18%)'), data: baseline },
                        { label: this._t('chart_ds_floor', 'Combination floor (11.2%)'), data: floor }
                    ]
                },
                forecastChart: {
                    labels: allLabels,
                    datasets: [
                        { label: this._t('chart_ds_hist', 'Historical (2018-2025)'), data: historicalSeries },
                        { label: this._t('chart_ds_forecast', '12-month forecast'), data: pointSeries },
                        { label: this._t('chart_ds_upper', '95% upper'), data: upperSeries },
                        { label: this._t('chart_ds_lower', '95% lower'), data: lowerSeries }
                    ]
                }
            };
        }
        getPerformanceSummary(history) {
            if (!history || !history.length) return {};
            var totalScore = history.reduce(function(s, r) {
                return s + (r.results && r.results.score ? r.results.score : 0);
            }, 0);
            var maxScore = this.ROUNDS.length * 2;
            var lastResults = history[history.length - 1].results || {};
            var lastMape = lastResults.mape !== undefined ? lastResults.mape : 18.0;
            var lastMase = lastResults.mase !== undefined ? lastResults.mase : 1.62;
            var lastCov = lastResults.coverage !== undefined ? lastResults.coverage : 50;

            var overall = Math.round((totalScore / maxScore) * 100);

            // Bands are driven by the methodology score alone. The previous version also
            // gated on MAPE, and because MAPE is a deterministic function of the same
            // score the two thresholds disagreed: the 8-point and 15-point gates could
            // never fire. Intentional change, banding only - per-round points are unchanged.
            var perf = 'apprentice';
            if (totalScore >= 8) perf = 'competent';
            if (totalScore >= 12) perf = 'cfo_ready';
            if (totalScore >= 15) perf = 'rigorous';

            var labels = {
                apprentice: this._t('perf_apprentice', 'Apprentice quant'),
                competent: this._t('perf_competent', 'Competent forecaster'),
                cfo_ready: this._t('perf_cfo_ready', 'CFO-ready quant'),
                rigorous: this._t('perf_rigorous', 'Methodologically rigorous')
            };

            var insights = [];
            if (totalScore >= 14) {
                insights.push(this._t('ins_high', 'You executed the Box-Jenkins workflow end-to-end and recommended combination forecasting with calibrated intervals.'));
            } else if (totalScore >= 10) {
                insights.push(this._t('ins_mid', 'Solid SARIMA build, but the synthesis - combination plus calibration audit - is where the M-competition record really pays off.'));
            } else {
                insights.push(this._t('ins_low', 'Re-read the diagnostic stack: stationarity, decomposition, ACF/PACF, structural break, calibration. Each step you skipped costs MAPE.'));
            }
            if (lastCov !== null && lastCov !== undefined && (lastCov < 90 || lastCov > 96)) {
                insights.push(this._t('ins_calib', 'Interval calibration is off the 95% target - re-examine which method underwrote your reported intervals.'));
            }
            insights.push(this._t('ins_baseline', 'Excel baseline 18.0% MAPE. Best-possible-on-this-series is about 11.2% (combination of HW, SARIMA and Prophet).')
                + ' ' + this._t('ins_final', 'Your final 12-month MAPE') + ': ' + lastMape.toFixed(1) + '%.');

            return {
                totalScore: totalScore,
                maxScore: maxScore,
                overallScore: overall,
                composite: overall,
                score: overall,
                finalMape: lastMape,
                finalMase: lastMase,
                finalCoverage: lastCov,
                performance: perf,
                performanceKey: perf,
                performanceLabel: labels[perf],
                insights: insights
            };
        }

        formatCompletionMessage(summary) {
            var s = summary || {};
            var parts = [];
            parts.push('<div class="ts-sim-complete">');
            parts.push('<h3>' + this._t('done_title', 'Run complete') + '</h3>');
            parts.push('<p class="ts-sim-complete-band">' + (s.performanceLabel || '') + '</p>');
            parts.push('<ul class="ts-sim-complete-kpis">');
            parts.push('<li>' + this._t('kpi_score', 'Methodology Score') + ': '
                + (s.totalScore || 0) + ' / ' + (s.maxScore || 16)
                + ' (' + (s.overallScore || 0) + '/100)</li>');
            parts.push('<li>' + this._t('kpi_mape', 'Forecast MAPE') + ': '
                + (s.finalMape !== undefined ? s.finalMape.toFixed(1) : '--') + '%</li>');
            parts.push('<li>' + this._t('kpi_mase', 'MASE') + ': '
                + (s.finalMase !== undefined ? s.finalMase.toFixed(2) : '--') + '</li>');
            parts.push('<li>' + this._t('kpi_calib', '95% Interval Coverage') + ': '
                + (s.finalCoverage !== undefined ? s.finalCoverage : '--') + '%</li>');
            parts.push('</ul>');
            (s.insights || []).forEach(function(i) { parts.push('<p>' + i + '</p>'); });
            parts.push('</div>');
            return parts.join('');
        }


        getHint(state, results) {
            if (!results) return null;
            if (results.score === 0) return window.mySimulation.t('hint_wrong');
            if (results.score === 1) return window.mySimulation.t('hint_partial');
            if (state.domainState && state.domainState.coverage !== null && state.domainState.coverage !== undefined && (state.domainState.coverage < 90 || state.domainState.coverage > 96)) {
                return window.mySimulation.t('hint_calib');
            }
            return null;
        }

