        _updateBriefing(state) {
            var total = this.ROUNDS.length;
            var period = (state && state.currentPeriod) || 1;
            var controls = document.getElementById('decisionControls');
            var done = document.getElementById('runCompletePanel');

            if (period > total) {
                // Terminal state: no live decision panel once the run is over.
                if (controls) controls.style.display = 'none';
                if (done) {
                    done.style.display = 'block';
                    var ds = (state && state.domainState) || {};
                    done.innerHTML = '<h3>' + this._t('done_title', 'Run complete') + '</h3>'
                        + '<p>' + this._t('done_body', 'All rounds are locked. Your framework is on the record.') + '</p>'
                        + '<p class="ts-sim-done-score">' + this._t('kpi_score', 'Methodology Score')
                        + ': ' + (ds.cumulativeScore || 0) + ' / 16</p>';
                }
                var tagDone = document.getElementById('briefingRound');
                if (tagDone) tagDone.textContent = this._t('done_title', 'Run complete');
                return;
            }

            if (controls) controls.style.display = '';
            if (done) done.style.display = 'none';

            var idx = Math.min(period - 1, total - 1);
            var round = this._round(idx);
            var roundKey = round.id + ':' + this._lang();

            var tagEl = document.getElementById('briefingRound');
            if (tagEl) {
                tagEl.textContent = this._t('round_label', 'Round') + ' ' + round.id + ' '
                    + this._t('period_of', 'of') + ' ' + total;
            }

            var titleEl = document.getElementById('briefingTitle');
            if (titleEl) titleEl.textContent = round.title;

            var bodyEl = document.getElementById('briefingText');
            if (bodyEl) bodyEl.innerHTML = round.description;

            var formEl = document.getElementById('briefingFormula');
            if (formEl) formEl.textContent = round.formula || '';

            var sel = document.getElementById('choiceSelect');
            if (sel && this._renderedRound !== roundKey) {
                // Rebuild only when the round or the language actually changed, so a stray
                // re-render can never wipe an answer the player has already selected.
                var keep = sel.value;
                sel.innerHTML = '';
                var ph = document.createElement('option');
                ph.value = '';
                ph.textContent = this._t('choice_placeholder', 'Select a move...');
                sel.appendChild(ph);
                round.options.forEach(function(opt) {
                    var o = document.createElement('option');
                    o.value = 'r' + round.id + 'o_' + opt.val;
                    o.textContent = opt.text;
                    sel.appendChild(o);
                });
                // No answer is pre-selected: the previous version defaulted to the last
                // option, which is the score-2 answer in every round.
                // A language switch on the same round keeps the choice already made.
                var sameRound = this._renderedRound !== null && String(this._renderedRound).split(':')[0] === String(round.id);
                sel.value = ((this._renderedRound === null || sameRound) && keep) ? keep : '';
                this._renderedRound = roundKey;
            }

            var rat = document.getElementById('rationaleInput');
            if (rat && rat.getAttribute('data-round') !== String(round.id)) {
                rat.value = '';
                rat.setAttribute('data-round', String(round.id));
            }
        }


        _buildBaselineSeries() {
            var labels = [];
            var values = [];
            var months = ['Jan', 'Feb', 'Mar', 'Apr', 'May', 'Jun', 'Jul', 'Aug', 'Sep', 'Oct', 'Nov', 'Dec'];
            for (var t = 0; t < 96; t++) {
                var trend = 26000 * Math.pow(1.025, t / 12);
                var seasonal = 1 + 0.20 * Math.cos(2 * Math.PI * ((t % 12) - 11) / 12);
                var brk = t >= 75 ? 0.92 : 1.0;
                var noise = 1 + 0.025 * Math.sin(t * 1.7 + 0.3) + 0.02 * Math.sin(t * 0.6 + 1.1);
                var v = Math.round(trend * seasonal * brk * noise);
                labels.push(months[t % 12] + ' ' + (2018 + Math.floor(t / 12)));
                values.push(v);
            }
            return labels.map(function(lab, i) { return { label: lab, value: values[i] }; });
        }

        _buildForecastSeries(frac) {
            var months = ['Jan', 'Feb', 'Mar', 'Apr', 'May', 'Jun', 'Jul', 'Aug', 'Sep', 'Oct', 'Nov', 'Dec'];
            var labels = months.map(function(m) { return m + ' 2026'; });
            var point = [];
            var upper = [];
            var lower = [];
            var baseLevel = 26000 * Math.pow(1.025, 96 / 12) * 0.92;
            for (var h = 0; h < 12; h++) {
                var seasonal = 1 + 0.20 * Math.cos(2 * Math.PI * (h - 11) / 12);
                var trendMult = Math.pow(1.025, (h + 1) / 12);
                var biasMult = 1 + (1 - frac) * 0.06;
                var p = Math.round(baseLevel * seasonal * trendMult * biasMult);
                var widthFrac = (0.18 - frac * 0.10) * Math.sqrt(1 + h / 6);
                var u = Math.round(p * (1 + widthFrac));
                var l = Math.round(p * (1 - widthFrac));
                point.push(p);
                upper.push(u);
                lower.push(l);
            }
            return { labels: labels, point: point, upper: upper, lower: lower };
        }

